test_that("execution flags are scalar and safe by default", { skip_if_not_installed("optparse"); x<-parse_pipeline_args(character()); expect_true(is.logical(x$dry_run)); expect_true(isTRUE(resolve_execution_choice(x)$dry_run)); expect_false(resolve_execution_choice(utils::modifyList(x,list(execute=TRUE)))$dry_run); expect_error(resolve_execution_choice(utils::modifyList(x,list(dry_run=TRUE,execute=TRUE))),"only one"); expect_error(parse_pipeline_args(c("--dry-run","false"))); expect_error(parse_pipeline_args(c("--execute","true"))) })
test_that("CLI output root is a character option", { skip_if_not_installed("optparse"); x<-parse_pipeline_args(c("--output-root","runtime/cds-datagrab")); expect_type(x$output_root,"character"); expect_true(is.logical(x$overwrite)); expect_true(is.logical(x$rebuild_all_weeks)) })
